require('dotenv').config();

// Singleton MongoClient per documentdb-driver & documentdb-connection guidance
let client;

function getClient() {
  if (client) return client;
  const uri = process.env.DOCUMENTDB_URI;
  if (!uri) throw new Error('DOCUMENTDB_URI is not set in the environment');

  // Default options chosen for a long-running Express server.
  // If you run in serverless, reduce maxPoolSize/minPoolSize per docs.
  client = new MongoClient(uri, {
    // Tunable: these defaults are reasonable for a demo server
    maxPoolSize: 50,
    minPoolSize: 10,
    connectTimeoutMS: 10000,
    socketTimeoutMS: 30000,
    retryWrites: true,
    retryReads: true,
  });
  return client;
}

async function getDb(name = 'sample_fintech_18') {
  const c = getClient();
  if (!c.topology || !c.topology.s.state || c.topology.s.state !== 'connected') {
    await c.connect();
  }
  return c.db(name);
}

module.exports = { getClient, getDb };
"}

